import {pfStatusRows} from './admin-pf-status.mjs?v=2';
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
const labels={pending_payment:'Afventer betalingsreservation',draft:'Kladde',sent:'Sendt til accept',accepted:'Accepteret',rejected:'Afvist',converted:'Oprettet som ordre',confirmed:'Bekræftet',cancelled:'Annulleret',unpaid:'Ikke betalt',reserved:'Reserveret',paid:'Betalt',waiting:'Afventer',ready:'Klar',in_progress:'I produktion',completed:'Afsluttet',unshipped:'Ikke afsendt',partial:'Delvist afsendt',shipped:'Afsendt',published:'Afventer kundesvar',approved:'Godkendt',changes:'Ændringer ønsket',queued:'I kø',running:'Behandles',done:'Færdig',failed:'Fejl',uncertain:'Kræver afstemning',administrator:'Administrator',sales:'Salg',production:'Produktion',accountant:'Bogholder',customer:'Kunde'};
const name=s=>labels[s]||s,amount=n=>(n/100).toLocaleString('da-DK',{style:'currency',currency:'DKK'}),date=s=>s?new Date(s).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'}):'Mangler';let actor,customers=[],products=[];
function say(s){$('status').textContent=s||'';}
async function api(path,body,key){const r=await fetch('/api/backoffice'+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json','X-Smerch-Admin':'1','Idempotency-Key':key||crypto.randomUUID()}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'Handlingen mislykkedes.');return data;}
const can=(...roles)=>actor.role==='administrator'||roles.includes(actor.role);
function button(parent,label,fn){const b=el('button',label);b.type='button';b.onclick=async()=>{b.disabled=true;say('');try{await fn();}catch(e){say(e.message);}finally{b.disabled=false;}};parent.append(b);return b;}
function link(parent,label,href){const a=el('a',label);a.href=href;parent.append(a);return a;}
function input(parent,label,value='',type='text'){const wrap=el('label',label),field=el(type==='textarea'?'textarea':'input');if(type!=='textarea')field.type=type;field.value=value??'';wrap.append(field);parent.append(wrap);return field;}
function select(parent,label,choices,value){const wrap=el('label',label),field=el('select');for(const [v,t] of choices){const o=el('option',t);o.value=v;field.append(o);}field.value=value||choices[0]?.[0];wrap.append(field);parent.append(wrap);return field;}
function form(parent,title,submit){const f=el('form');f.append(el('h3',title));const b=el('button','Gem');b.type='submit';let key=crypto.randomUUID();f.onsubmit=async e=>{e.preventDefault();b.disabled=true;say('');try{await submit();key=crypto.randomUUID();}catch(err){say(err.message);}finally{b.disabled=false;}};parent.append(f);return {f,done:()=>f.append(b),key:()=>key};}
function table(parent,head,rows){if(!rows.length){parent.append(el('p','Ingen poster endnu.'));return;}const t=el('table'),h=el('tr');head.forEach(x=>h.append(el('th',x)));t.append(h);for(const values of rows){const row=el('tr');for(const value of values){const td=el('td');if(value instanceof Node)td.append(value);else td.textContent=value??'—';row.append(td);}t.append(row);}parent.append(t);}
async function start(){try{actor=await api('/session');$('login').hidden=true;$('tabs').hidden=false;$('logout').hidden=false;$('identity').textContent=actor.username+' · '+name(actor.role);$('tabs').replaceChildren();for(const [title,fn,allowed] of [['Ordrer',orders,true],['Kunder',customerList,can('sales')],['Tilbud',quoteList,can('sales','customer')],['Produkter og priser',productList,can('sales')],['Brugere',userList,can()],['Drift',health,can()]])if(allowed)button($('tabs'),title,fn);if(location.hash.startsWith('#order='))await detail(decodeURIComponent(location.hash.slice(7)));else await orders();}catch(e){say(e.message);$('login').hidden=false;}}
$('login').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),r=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(data))});if(r.ok)await start();else say('Login mislykkedes. Kontrollér oplysningerne.');};$('logout').onclick=async()=>{await fetch('/api/admin/logout',{method:'POST',headers:{'X-Smerch-Admin':'1'}});location.reload();};
function page(title){const c=$('content');c.replaceChildren(el('h2',title));say('');return c;}
async function customerList(){const c=page('Kunder');customers=await api('/customers');table(c,['Kunde','E-mail',''],customers.map(row=>{const tools=el('div');button(tools,'Redigér',()=>customerForm(c,row));return [row.name,row.email,tools];}));button(c,'Opret kunde',()=>customerForm(c,{}));}
function customerForm(c,row){const fields={};const f=form(c,row.id?'Redigér kunde':'Ny kunde',async()=>{await api('/customers',{...Object.fromEntries(Object.entries(fields).map(([k,v])=>[k,v.value])),id:row.id,version:row.version},f.key());await customerList();});for(const [k,label] of Object.entries({name:'Navn / firma',email:'E-mail',contact:'Kontaktperson',address:'Faktureringsadresse',cvr:'CVR (valgfrit)',ean:'EAN (valgfrit)',reference:'Kundereference',phone:'Telefon'}))fields[k]=input(f.f,label,row[k],k==='address'?'textarea':'text');f.done();}
async function productList(){const c=page('Produkter og priser');c.append(el('p','Produktvarianter til manuelle tilbud. Webshoppens PF-priser beregnes fortsat af den eksisterende prismotor.'));products=await api('/products');table(c,['Produkt','Varenummer','Priser'],products.map(p=>[p.name,p.sku,p.prices.map(v=>`${v.minimum_quantity}+ stk.: ${amount(v.unit_minor)}`).join('\n')]));if(can()){const fields={};const f=form(c,'Tilføj produkt / variant',async()=>{await api('/products',Object.fromEntries(Object.entries(fields).map(([k,v])=>[k,v.value])),f.key());await productList();});fields.id=select(f.f,'Produkt',[['','Opret nyt produkt'],...Array.from(new Map(products.map(p=>[p.id,p.name])).entries())]);for(const [key,label] of Object.entries({name:'Produktnavn',sku:'Varenummer',color:'Farve',size:'Størrelse',material:'Materiale',printMethod:'Trykmetode',unitPrice:'Stykpris ekskl. moms (DKK)',minimumQuantity:'Minimumsantal'}))fields[key]=input(f.f,label,key==='minimumQuantity'?'1':'');f.done();}}
async function quoteList(){const c=page('Tilbud');const rows=await api('/quotes');table(c,['Dato','Kunde','Status','I alt',''],rows.map(q=>{const tools=el('div');button(tools,'Åbn',()=>quoteView(q));return [date(q.created_at),q.snapshot.customer.name,name(q.status),amount(q.snapshot.total),tools];}));if(can('sales'))button(c,'Nyt tilbud',()=>quoteForm());}
async function quoteForm(row){const c=page(row?'Redigér tilbud':'Nyt tilbud');[customers,products]=await Promise.all([api('/customers'),api('/products')]);if(!customers.length){c.append(el('p','Opret en kunde først.'));return;}const old=row?.snapshot||{},lines=[];let customer,reference,terms,notes,freight;const f=form(c,'Tilbudsoplysninger',async()=>{await api('/quotes',{id:row?.id,version:row?.version,customerId:customer.value,reference:reference.value,paymentTerms:terms.value,notes:notes.value,freight:freight.value,lines:lines.map(l=>Object.fromEntries(Object.entries(l).map(([k,v])=>[k,k==='personalised'?v.checked:v.value])))},f.key());await quoteList();});customer=select(f.f,'Kunde',customers.map(x=>[x.id,x.name]),row?.customer_id);reference=input(f.f,'Kundereference',old.reference);terms=input(f.f,'Betalingsbetingelser',old.paymentTerms,'textarea');notes=input(f.f,'Interne specifikationer',old.notes,'textarea');freight=input(f.f,'Fragt ekskl. moms',(old.freight===undefined?0:old.freight/100).toFixed(2));const list=el('div');f.f.append(list);function addLine(source={}){const box=el('div');box.className='line';list.append(box);const l={};l.variantId=select(box,'Gemte varianter (pris hentes på serveren)',[['','Manuel tilbudslinje'],...products.map(p=>[p.variantId,p.name+' · '+p.sku])],source.variantId);for(const [k,label,value] of [['description','Produktbeskrivelse',source.description],['sku','Varenummer',source.sku],['variant','Variant',source.variant],['quantity','Antal',source.quantity||1],['unitPrice','Stykpris ekskl. moms',source.unitPrice||'0'],['printPrice','Tryk pr. stk. ekskl. moms',source.printPrice||'0'],['setup','Opstart ekskl. moms',source.setup||'0'],['discountPercent','Rabat i %',source.discountPercent||'0']])l[k]=input(box,label,value);l.personalised=input(box,'Kræver korrektur','','checkbox');l.personalised.checked=!!source.personalised;lines.push(l);}for(const line of old.lines||[{}])addLine(line);button(f.f,'Tilføj varelinje',()=>addLine());f.done();}
function quoteView(q){const c=page('Tilbud');c.append(el('p',q.id+' · '+name(q.status)),el('h3',q.snapshot.customer.name));table(c,['Vare','Antal','Nettobeløb'],q.snapshot.lines.map(l=>[l.description,l.quantity,amount(l.net)]));c.append(el('p','Fragt: '+amount(q.snapshot.freight)+' · Moms: '+amount(q.snapshot.vat)+' · I alt: '+amount(q.snapshot.total)),el('p','Betalingsbetingelser: '+(q.snapshot.paymentTerms||'Mangler')));if(q.status==='draft'&&can('sales')){button(c,'Redigér tilbud',()=>quoteForm(q));button(c,'Markér sendt til accept',async()=>{await api('/quotes/'+q.id,{version:q.version,status:'sent'});await quoteList();});}if(q.status==='sent'){let evidence;if(actor.role!=='customer')evidence=input(c,'Dokumentation for kundens accept (fx dato og mailreference)');button(c,'Acceptér tilbud',async()=>{await api('/quotes/'+q.id,{version:q.version,status:'accepted',evidence:evidence?.value});await quoteList();});button(c,'Afvis tilbud',async()=>{await api('/quotes/'+q.id,{version:q.version,status:'rejected'});await quoteList();});}if(q.status==='accepted'&&can('sales'))button(c,'Opret ordre fra accepteret tilbud',async()=>{const result=await api('/quotes/'+q.id,{version:q.version,status:'converted'});await detail(result.id);});if(q.order_id)button(c,'Åbn ordre',()=>detail(q.order_id));}
async function orders(){const c=page('Ordrer');const rows=await api('/orders');table(c,['Mockup','Dato og tid / reference','Kunde / bestilling','Betaling','Produktion','Levering',''],rows.map(o=>{const tools=el('div');button(tools,'Åbn ordre',()=>detail(o.id));const preview=el('div');if(o.mockup){const img=el('img');img.src=o.mockup;img.alt='Ordremockup';img.width=80;img.height=80;img.style.objectFit='contain';preview.append(img);}else preview.textContent='Intet mockup gemt';return [preview,date(o.created_at)+'\n'+o.id,o.customerName+'\n'+o.items.map(l=>l.quantity+' × '+(l.description||l.sku)).join('\n'),name(o.payment_status),name(o.production_status),name(o.delivery_status),tools];}));}
async function detail(id){const o=await api('/orders/'+encodeURIComponent(id)),c=page('Ordre');button(c,'← Alle ordrer',orders);c.append(el('h3',o.id),el('p',date(o.created_at)));const states=el('div');for(const [label,value] of [['Ordre',o.order_status],['Betaling',o.payment_status],['Produktion',o.production_status],['Levering',o.delivery_status]]){const b=el('span',label+': '+name(value));b.className='badge';states.append(b);}c.append(states);if(o.source==='checkout')c.append(el('p','Betalingsordre: betaling og PF-frigivelse håndteres fortsat i den eksisterende ordrevisning. Her registrerer du det interne arbejde.'));for(const legacy of o.legacyOrders||[]){if(actor.role!=='customer'){link(c,'Åbn original PF-ordre '+(legacy.pfOrderNumber||legacy.id),'/admin/pf-orders#order='+legacy.id);for(const [label,value] of pfStatusRows(legacy))c.append(el('p',label+': '+value));}}if(o.snapshot.missingHistoricalDetails)c.append(el('p','Ældre ordre: visse variantoplysninger blev ikke gemt historisk. Kontrollér originalordren.'));table(c,['Vare / variant','Bestilt','Afsendt','Ekskl. moms'],o.lines.map(l=>[l.description||'Beskrivelse mangler',l.quantity,l.shipped,l.net_minor===null?'Mangler':amount(l.net_minor)]));
 const visuals=el('div');visuals.className='tools';for(const m of o.mockups||[]){const img=el('img');img.src='/api/backoffice/orders/'+id+'/mockup?index='+m.index;img.alt='Designmockup · '+m.name;img.width=160;img.height=160;img.style.objectFit='contain';visuals.append(img);}if(visuals.childElementCount)c.append(visuals);const files=el('article');files.append(el('h3','Filer og korrekturversioner'));for(const file of o.files){if(actor.role!=='customer'&&file.mime_type.startsWith('image/')){const img=el('img');img.src='/api/backoffice/files/'+file.id;img.alt=file.name;img.width=140;img.height=140;img.style.objectFit='contain';files.append(img);}link(files,`v${file.version} · ${file.name}`,`/api/backoffice/files/${file.id}`);files.append(el('br'));}for(const p of o.proofs)files.append(el('p',`Korrektur v${p.version}: ${name(p.status)}${p.decision_at?' · '+date(p.decision_at):''}${p.comment?' · '+p.comment:''}`));c.append(files);
 if(can('sales','production')){const upload=input(files,'Upload PDF, PDF-kompatibel AI, PNG eller JPEG','','file');button(files,'Gem ny filversion',async()=>{const file=upload.files?.[0];if(!file||file.size>10*1024*1024)throw Error('Vælg en fil på højst 10 MB.');const buffer=await file.arrayBuffer();let binary='';for(const byte of new Uint8Array(buffer))binary+=String.fromCharCode(byte);await api('/orders/'+id+'/files',{name:file.name,base64:btoa(binary)});await detail(id);});const pdfs=o.files.filter(f=>f.mime_type==='application/pdf');if(pdfs.length&&o.source!=='checkout'){const chosen=select(files,'PDF til ny korrektur',pdfs.map(p=>[p.id,p.name+' · v'+p.version]));button(files,'Gør PDF klar til kundegodkendelse',async()=>{await api('/orders/'+id+'/proofs',{fileId:chosen.value});await detail(id);});}}
 if(actor.role==='customer'){const current=o.proofs.at(-1);if(current?.status==='published'){const comment=input(files,'Kommentar / ændringsønsker','','textarea');for(const [status,label] of [['approved','Godkend korrektur'],['changes','Bed om ændringer']])button(files,label,async()=>{await api('/orders/'+id+'/proof-decision',{proofId:current.id,status,comment:comment.value});await detail(id);});}}
 if(can('production')&&o.source!=='checkout'){const p=el('article');p.append(el('h3','Produktion'));const deadline=input(p,'Deadline',o.production?.deadline||'','date'),spec=input(p,'Produktionsspecifikation',o.production?.specification||'','textarea');const next={waiting:['ready','Markér klar til produktion'],ready:['in_progress','Registrér produktionsstart'],in_progress:['completed','Registrér afsluttet produktion']}[o.production_status];if(next)button(p,next[1],async()=>{await api('/orders/'+id+'/production',{version:o.version,status:next[0],deadline:deadline.value,specification:spec.value});await detail(id);});c.append(p);
 if(o.production_status==='completed'&&o.delivery_status!=='shipped'){let shipped,carrier,tracking,url;const quantities=[];const f=form(c,'Registrér afsendelse / delleverance',async()=>{await api('/orders/'+id+'/shipments',{version:o.version,shippedAt:shipped.value,carrier:carrier.value,trackingNumber:tracking.value,trackingURL:url.value,lines:quantities.filter(l=>Number(l.field.value)>0).map(l=>({id:l.id,quantity:Number(l.field.value)}))},f.key());await detail(id);});shipped=input(f.f,'Faktisk afsendelsesdato','','date');carrier=input(f.f,'Transportør');tracking=input(f.f,'Trackingnummer');url=input(f.f,'Trackinglink');for(const l of o.lines)quantities.push({id:l.id,field:input(f.f,`${l.description||l.sku}: afsendt nu (rest ${l.quantity-l.shipped})`,'0','number')});f.done();}}
 const delivery=el('article');delivery.append(el('h3','Forsendelser'));for(const s of o.shipments){delivery.append(el('p',`${s.shipped_at} · ${s.carrier||'Transportør mangler'} · ${s.tracking_number||''}`));if(s.tracking_url)link(delivery,'Følg pakken',s.tracking_url);}if(!o.shipments.length)delivery.append(el('p','Ingen afsendelser registreret.'));c.append(delivery);
 const docs=el('article');docs.append(el('h3','Dokumenter'));for(const d of o.documents){if(d.ready)link(docs,`${d.type==='basis'?'Fakturagrundlag':d.type==='receipt'?'Kvittering':'Forsendelsesbekræftelse'} · v${d.version} · ${date(d.created_at)}`,`/api/backoffice/documents/${d.id}`);else docs.append(el('p','PDF v'+d.version+' behandles. Se Drift ved fejl.'));docs.append(el('br'));}button(docs,'Opdatér dokumentstatus',()=>detail(id));if(can('sales','accountant'))for(const [type,label] of [['basis','Fakturagrundlag'],['shipment','Forsendelsesbekræftelse'],['receipt','Kvittering']])button(docs,'Opret '+label,()=>documentForm(id,type,docs));c.append(docs);
 if(can('accountant')){let number,evidence;const f=form(c,'Registrér endeligt fakturanummer fra e-conomic',async()=>{await api('/orders/'+id+'/invoice',{version:o.version,number:number.value,evidence:evidence.value},f.key());await detail(id);});number=input(f.f,'Fakturanummer',o.invoice_number);evidence=input(f.f,'Reference / dokumentation');f.done();if(o.source==='quote'&&o.delivery_status==='shipped'&&o.payment_status!=='paid'){let paidAt,paidAmount,method,ref;const pay=form(c,'Registrér dokumenteret betaling (hæver ingen penge)',async()=>{await api('/orders/'+id+'/payment',{version:o.version,paidAt:paidAt.value,amount:paidAmount.value,method:method.value,reference:ref.value},pay.key());await detail(id);});paidAt=input(pay.f,'Betalingsdato','','date');paidAmount=input(pay.f,'Modtaget beløb inkl. moms');method=input(pay.f,'Betalingsmetode');ref=input(pay.f,'Dokumentationsreference (bankpost / bilag)');pay.done();}}
 if(can('sales','accountant','production'))messageForm(c,o);
 if(actor.role!=='customer'){const log=el('details');log.append(el('summary','Historik'));for(const event of o.audit)log.append(el('p',`${date(event.at)} · ${event.actor_id} · ${event.action}`));c.append(log);}
}
function messageForm(c,o){let audience,recipient,subject,text,attachment;const f=form(c,'Besked / intern note',async()=>{await api('/orders/'+o.id+'/messages',{audience:audience.value,recipient:recipient.value,subject:subject.value,text:text.value,documentId:attachment.value||undefined},f.key());await detail(o.id);});audience=select(f.f,'Modtagergruppe',[['internal','Intern note (ingen mail)'],['customer','Kunde'],['accountant','Bogholder'],['production','Produktion']]);recipient=input(f.f,'Modtagerens e-mail (ved afsendelse)');subject=input(f.f,'Emne','Smerch-ordre '+o.id);text=input(f.f,'Besked','','textarea');attachment=select(f.f,'Vedhæft dokument',[['','Intet bilag'],...o.documents.filter(d=>d.ready).map(d=>[d.id,(d.type==='basis'?'Fakturagrundlag':d.type==='receipt'?'Kvittering':'Forsendelsesbekræftelse')+' · v'+d.version])]);f.f.append(el('p','Kontrollér modtager og indhold. Kundemails kræver kundens registrerede adresse.'));f.done();for(const m of o.messages)c.append(el('p',`${date(m.created_at)} · ${m.audience} · ${name(m.status)} · ${m.subject}`));}
async function documentForm(id,type,parent){const d=await api('/orders/'+id+'/document-draft?type='+type),fields=[];const f=form(parent,'Gennemse dokumentoplysninger',async()=>{for(const [obj,key,field,money] of fields)obj[key]=money?(field.value===''?null:Math.round(Number(field.value.replace(',','.'))*100)):key==='quantity'?Number(field.value):field.value;await api('/orders/'+id+'/documents',d,f.key());await detail(id);say('PDF’en er sat i kø. Opdatér dokumentstatus om et øjeblik.');});function add(obj,key,label,money=false){const value=money?(obj[key]===null?'':(obj[key]/100).toFixed(2)):obj[key];const field=input(f.f,label,value,['address','notes','paymentTerms'].includes(key)?'textarea':'text');if((type==='receipt'&&(money||key==='quantity'))||(type==='shipment'&&key==='quantity'))field.readOnly=true;fields.push([obj,key,field,money]);}f.f.append(el('p','Reference: '+d.reference+' · '+d.paymentStatus));for(const k of ['legalName','address','cvr','email','phone'])add(d.company,k,'Afsender · '+k);for(const k of ['name','contact','address','cvr','ean','email','reference'])add(d.customer,k,'Kunde · '+k);if(type==='shipment'){for(const k of ['deliveryAddress','shipDate','carrier','tracking'])add(d,k,k);}for(const [i,l]of d.lines.entries()){f.f.append(el('h4','Vare '+(i+1)));for(const k of ['description','variant','quantity','discount'])add(l,k,k);if(type!=='shipment')add(l,'net','Linjetotal ekskl. moms',true);}if(type!=='shipment'){add(d,'freight','Fragt ekskl. moms',true);add(d,'vat','Moms',true);add(d,'paymentTerms','Betalingsbetingelser');}add(d,'notes',type==='basis'?'Bemærkninger til bogholderen':'Bemærkninger til kunden');f.done();}
async function userList(){const c=page('Brugere og roller'),rows=await api('/users');table(c,['Brugernavn','Rolle','Status',''],rows.map(u=>{const tools=el('div');if(u.id!==actor.id&&u.id!=='bootstrap-admin'&&u.enabled)button(tools,'Deaktivér',async()=>{await api('/users/'+u.id+'/disable',{});await userList();});return [u.username,name(u.role),u.enabled?'Aktiv':'Deaktiveret',tools];}));customers=await api('/customers');let username,password,role,customer;const f=form(c,'Opret bruger',async()=>{await api('/users',{username:username.value,password:password.value,role:role.value,customerId:customer.value},f.key());await userList();});username=input(f.f,'Brugernavn');password=input(f.f,'Adgangskode (mindst 12 tegn)','','password');password.autocomplete='new-password';role=select(f.f,'Rolle',Object.entries(labels).filter(([k])=>['administrator','sales','production','accountant','customer'].includes(k)));customer=select(f.f,'Kunde (kun ved kunderolle)',[['','Vælg kunde'],...customers.map(c=>[c.id,c.name])]);f.done();}
async function health(){const c=page('Drift'),[h,jobs]=await Promise.all([api('/health'),api('/jobs')]);c.append(el('p',`Database: ${h.integrity?'OK':'FEJL'} · Opgaver i kø: ${h.pendingJobs} · Kræver opmærksomhed: ${h.failedJobs}`));table(c,['Type','Status','Forsøg','Fejlkode','Tid'],jobs.map(j=>[j.kind,name(j.status),j.attempts,j.error_code,date(j.created_at)]));c.append(el('p','Mail med ukendt afsendelsesstatus genforsøges ikke automatisk. Afstem mailkontoen før ny afsendelse.'));}
start();
